export interface BlogSection {
  num?: string;
  kicker?: string;
  head?: string;
  /** subsection: renders as an h3 under the previous h2 and stays out of the TOC */
  sub?: boolean;
  /** named built-in site figure rendered by the post page ("rs1"|"rs2"|"rs3":
   *  the room-model scenes from /platform/taxonomy) — for sections that need a
   *  site graphic rather than an image file */
  fig?: string;
  /** data table: one header row plus body rows, rendered dark-themed */
  table?: { cols: string[]; rows: string[][] };
  paras?: string[];
  bullets?: string[];
  quote?: string;
  quoteWho?: string;
  /** paragraphs that follow a quote inside the same section */
  after?: string[];
  /** self-hosted path */
  img?: string;
  /** where it was fetched from, and the fallback when the file is absent */
  imgRemote?: string;
  caption?: string;
  /** portrait assets (phone renders) need a tall frame, not a 16:9 band */
  imgRatio?: string;
}

