export const blogPostBySlug = (slug: string): BlogPost | undefined =>
  BLOG_POSTS.find((p) => p.slug === slug);

/** Grid page size for the hub and its numbered pages (the featured lead on page
 *  one sits outside this count). One constant so the hub, page/[n] and the pager
 *  arithmetic can never disagree. */
export const PER_PAGE = 12;

export const blogCount = (key: string): number =>
  key === "all" ? BLOG_POSTS.length : BLOG_POSTS.filter((p) => p.topic === key).length;

/** Hub order: the source's, with anything it does not name falling to the end. */
export const BLOG_POSTS_ORDERED: BlogPost[] = BLOG_POSTS.slice().sort((a, b) => {
  const r = (s: string) => {
    const i = BLOG_ORDER.indexOf(s);
    return i < 0 ? 999 : i;
  };
  return r(a.slug) - r(b.slug);
});

/** Where a reader of each topic should go next on the site — the middle card at the
 *  foot of every post. One destination per topic rather than one per post: a topic
 *  is exactly the granularity at which "the relevant part of the site" is a stable
 *  answer, and 45 hand-picked links would rot the first time a route moved. */
export const BLOG_DEST: Record<string, { route: Route; label: string; line: string }> = {
  meeting: {
    route: "platform/how",
    label: "How Polaris collaboration works",
    line: "The mechanics behind the meeting: what happens in the room, and what the room asks of the people in it.",
  },
  hybrid: {
    route: "solutions/hybrid",
    label: "Hybrid conferencing",
    line: "What a hybrid room needs when half the participants are somewhere else.",
  },
  workplace: {
    route: "solutions/corporate",
    label: "Corporate workspaces",
    line: "The estate view: standardising rooms across buildings without standardising the work.",
  },
  byom: {
    route: "platform/taxonomy",
    label: "BYOD, BYOM and room-hosted",
    line: "The ladder this post sits on, defined: which rung a room is on, and what changes at each step.",
  },
  security: {
    route: "platform/security",
    label: "Security & Trust Center",
    line: "The posture behind the claims: secure boot, hardware device identity, certifications and the network model.",
  },
  education: {
    route: "solutions/education",
    label: "Education",
    line: "Lecture halls, active-learning rooms and 1:1 device fleets, from the campus AV team's side.",
  },
  guides: {
    route: "resources/docs",
    label: "Documentation hub",
    line: "The reference behind the explainer: port matrices, network requirements and deployment guides.",
  },
  people: {
    route: "resources/who",
    label: "Who we are",
    line: "The company behind the design decisions, and why ownership changes how they get made.",
  },
  news: {
    route: "products/family",
    label: "Meet the Polaris family",
    line: "What was announced, and where it sits in the product line today.",
  },
};

/** The destination for one post, falling back to the platform overview. */
export const blogDest = (topic: string) =>
  BLOG_DEST[topic] ?? BLOG_DEST.meeting;
